export function outingBoard(s,{E,picture,esc}){
 const current=E.outingStatus(s),claimed=s.outingClaimDays.includes(s.day),offers=current||claimed?[]:E.outingOffers(s);
 const past=s.outingLog.filter(v=>v.day<s.day).slice(0,5);
 const history=past.length?`<details class="outing-history"><summary>Your recent outing memories · ${past.length}</summary>${past.map(v=>`<p><strong>Day ${v.day} · ${esc(v.title)}</strong><span>${E.money(v.spent)} at completion · +${v.xp} XP</span></p>`).join('')}</details>`:'';
 const header=`<div class="outing-heading"><div><div class="eyebrow">YOUR DAY · YOUR PACE</div><h3 id="outing-heading">A small plan. A good afternoon.</h3><p>Choose a daily outing with real models to discover. One outing reward each day; your story chapters continue alongside it.</p></div><span class="outing-date">DAY ${s.day}<small>${E.mallOf(s).name}</small></span></div>${history}`;
 if(claimed){const log=s.outingLog.find(v=>v.day===s.day);return `<section class="outing-board" aria-labelledby="outing-heading">${header}<div class="outing-celebration"><span aria-hidden="true">✓</span><div><small>TODAY’S OUTING COMPLETE</small><h4>${esc(log?.title||current?.title||'An afternoon well spent')}</h4><p>Your reward is collected. Enjoy the rest of the mall; fresh outings arrive tomorrow.</p></div><button class="button secondary" data-action="track-story">Follow my story ${E.activeMission(s)?.chapter||''} →</button></div></section>`;}
 if(current){
  const {plan}=current,tracking=!!s.outingFocus,percent=Math.round(current.complete/current.total*100);
  const cards=current.items.map(i=>{
   const target=i.product,st=E.storeById(target.store),mall=E.mallForStore(s,target.store),value=E.price(s,target),total=value+Math.round(value*E.TAX);
   return `<article class="outing-item ${i.done?'done':''}"><div class="outing-photo">${picture(i.product)}</div><div class="outing-item-copy"><small>${esc(i.product.brand)}</small><h4>${esc(i.product.name)}</h4><p>${esc(st.name)} · ${esc(mall.name)}</p><strong>${E.money(total)} <small>incl. game tax</small></strong><div class="outing-checks"><span class="${i.inspected?'done':''}">${i.inspected?'✓':'○'} Label read</span>${i.fit?`<span class="${i.fitted?'done':''}">${i.fitted?'✓':'○'} Usual size tried</span>`:''}${i.buy?`<span class="${i.purchase?'done':''}">${i.purchase?'✓':'○'} New purchase kept</span>`:''}</div><button class="button secondary small" data-action="outing-product" data-id="${esc(i.productId)}">${i.done?'Revisit this model':'Find this model'} →</button></div></article>`;
  }).join('');
  return `<section class="outing-board" aria-labelledby="outing-heading">${header}<div class="outing-active"><div class="outing-summary"><span class="outing-symbol" aria-hidden="true">${current.emoji}</span><div><small>${tracking?'TRACKING THIS OUTING':'YOUR ACTIVE OUTING'}</small><h4>${current.title}</h4><p>${current.description}</p></div><div class="outing-reward">+${current.xp} XP<small>${current.cash?'+'+E.money(current.cash)+' game money':'A free afternoon'}</small></div></div><div class="outing-progress" role="progressbar" aria-label="Outing steps completed" aria-valuenow="${current.complete}" aria-valuemin="0" aria-valuemax="${current.total}"><i style="width:${percent}%"></i></div><div class="outing-progress-copy"><strong>${current.complete} / ${current.total} steps complete</strong><span>${current.budget?E.money(current.spent)+' / '+E.money(current.budget)+' outing allowance':'No purchase required'}</span></div>${current.overBudget?'<p class="outing-warning">The matching purchases exceed this allowance. You can return an eligible item and find a lower-priced matching model, or choose a different outing.</p>':''}<div class="outing-items">${cards}</div><details class="outing-step-list" ${current.ready?'open':''}><summary>Every step in your plan</summary><ol>${current.steps.map(step=>`<li class="${step.done?'done':''}"><span aria-hidden="true">${step.done?'✓':'○'}</span><span>${esc(step.label)}</span></li>`).join('')}</ol>${plan.template==='window'?`<button class="button secondary" data-action="venue" data-id="rest">Walk to a bench · free · 30 min</button>`:''}</details><p class="outing-note">${current.items.some(i=>i.buy)?'Only new, kept purchases after accepting count. Fitting goals require your usual purchased size. Matching models at other branches count, too.':'Read three different model labels today and take a new bench break after accepting.'} The outing allowance covers these finds; meals and other purchases are separate. No money is reserved.</p><div class="outing-actions"><button class="button orange" data-action="${current.ready?'outing-claim':'outing-follow'}">${current.ready?'Collect '+current.xp+' XP'+(current.cash?' + '+E.money(current.cash):''):'Continue this outing →'}</button>${tracking?'<button class="button secondary" data-action="track-story">Track my story instead</button>':'<button class="button secondary" data-action="outing-track">Track this outing</button>'}<button class="text-button" data-action="outing-cancel">Choose a different outing</button></div></div></section>`;
 }
 return `<section class="outing-board" aria-labelledby="outing-heading">${header}<div class="outing-offers">${offers.map(o=>{const enough=E.remainingTime(s)>=o.minutes;return `<article class="outing-offer"><div class="outing-offer-top"><span aria-hidden="true">${o.emoji}</span><small>${o.budget?'SHOPPING ALLOWANCE':'JUST EXPLORING'}<strong>${o.budget?E.money(o.budget):'Free'}</strong></small></div><h4>${o.title}</h4><p>${o.description}</p><div class="outing-preview-photos">${o.items.slice(0,3).map(i=>`<div title="${esc(E.byId(i.productId).name)}">${picture(E.byId(i.productId))}</div>`).join('')}</div><p class="outing-model-names">${o.items.map(i=>esc(E.byId(i.productId).name)).join(' · ')}</p><div class="outing-offer-meta"><span>At least ${o.minutes} game min<small>Walking and queues add time</small></span><strong>+${o.xp} XP<small>${o.cash?'+'+E.money(o.cash)+' game money':'No spending needed'}</small></strong></div><button class="button ${enough?'orange':'secondary'} wide" data-action="outing-start" data-id="${o.id}" ${!enough?'disabled':''}>${enough?'Make this my outing':'Not enough time today'}</button></article>`;}).join('')}</div><p class="outing-note">Your ${E.money(s.dailyBudget)} daily spending target helps choose affordable finds from this mall. Product names and photos are real; stock, prices, allowances and rewards are game rules. Offer prices include game tax and exclude a one-use coupon.</p></section>`;
}
